  function planetThumb(p){return p.kind==='belt'?'<i class="belt-thumb" aria-hidden="true">⁙ ⁙ ⁙</i>':`<img class="orbit-thumb" src="assets/planet-thumbs/${esc(p.npc?(['outpost','garrison','charon','cargo','fracture'].includes(p.npcType)?p.npcType:'outpost'):p.moon?'moon':p.biome||'terrestrial')}.png" alt="" loading="lazy">`;}
  function planetOutcome(p){
    if(!p?.npc)return '';const intel=p.intel,b=intel?.battle,live=api.state.battles?.find(b=>b.target===p.id),values=v=>names.map((name,i)=>`<div><span>${name}</span><b>${number(v?.[i])}</b></div>`).join('');
    let html='<section class="planet-outcome"><div class="overline">战况与资源</div>';
    if(p.npcDailyResources)html+=`<p class="outcome-caption">Lv ${p.npcLevel} · 每日满额库存</p><div class="outcome-resources daily-resources">${values(p.npcDailyResources)}</div><p class="loot-explanation npc-daily-rule">每天北京时间 00:00 重置库存并补满舰队、防御；交战中顺延至结算。库存不自然增长或消耗，掠夺后减少，当天不回补。</p>`;
    if(live)html+=`<p class="combat-state">正在交战 · 进攻 ${live.counts[0]} / 防守 ${live.counts[1]}</p><button class="primary filled" data-map-battle="${esc(live.id)}">在星图查看实时交战 ↗</button>`;
    if(b){const delivery=b.delivery==='returning'?'运送中 · '+time(b.returnAt):b.delivery==='delivered'?'已送达出发星球':'掠夺已结算';html+=`<div class="outcome-heading"><strong>${live?'上一场 · ':''}${b.winner==='attacker'?'进攻胜利':b.winner==='defender'?'进攻失利':'双方撤离'}</strong><small>${new Date(b.at).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}</small></div><p class="outcome-caption">本次装载 · ${delivery}</p><div class="outcome-resources">${values(b.loot)}</div><p class="outcome-caption">我方损失 ${total(b.losses?.attacker)} 艘 · 击毁 ${total(b.losses?.defender)} 个单位${b.capacity!=null?' · 幸存货舱 '+number(b.capacity):''}</p><button class="text-button" data-map-replay="${esc(b.id)}">在原地回看战斗 ↗</button>`;}
    if(intel?.resources)html+=`<p class="outcome-caption">${intel.resourceSource==='post-battle-live'?'战后监测 · 当前剩余资源':'最近情报 · '+new Date(intel.resourceAt).toLocaleString('zh-CN')}</p><div class="outcome-resources remaining-resources">${values(intel.resources)}</div>${intel.defenders!=null?'<p class="outcome-caption">剩余守军 '+intel.defenders+' 个单位</p>':''}`;
    else html+=`<p class="outcome-caption">${intel?.refreshExpired?'据点已每日刷新，旧情报已过期，请重新侦察。':'当前剩余资源尚未探明，先派探测器侦察。'}</p>`;
    html+='<p class="loot-explanation">获胜后自动装载，返航自动入库，无需领取。野怪资源可全部掠夺，货舱足够即可清空库存；实际数量受幸存舰队货舱限制。</p>';
    if(intel?.resourceSource==='post-battle-live'&&!live)html+='<button class="primary" data-map-task="attack">带货船继续搜刮 ↗</button>';
    if((p.debris||[]).some(n=>n>0))html+='<button class="text-button" data-map-task="recycle">派回收舰收集残骸 ↗</button>';
    return html+'</section>';
  }
  async function openMapBattle(id){if(!scene)return;setChartPanel(null);await scene.prepareDeparture();go('system',{keepCamera:true});await scene.combat.openBattle(id);renderSystem();}
  async function openMapReplay(id){const data=await api.replay(id);if(!data)throw Error(api.error||'无法读取战报');if(!data.record?.frames?.length)throw Error('这份旧战报未保存空间录像，可在战报中查看结果。');if(scene){scene.combat.close();go('system',{keepCamera:true});await scene.combat.replayReport(id,data);renderMapCombat();}else{go('battle');await battle.start(data);}}
  let warWatch=0;
  async function openFactionWar(id){
    const generation=++warWatch;
    const read=async()=>{const response=await fetch('/api/faction-wars/'+id);const data=await response.json();if(!response.ok)throw Error(data.error);return data;};
    const data=await read();if(generation!==warWatch)return;
    scene.combat.close();go('system',{keepCamera:true});await scene.combat.replayReport('faction:'+id,data);renderMapCombat();
    const playback=scene.combat.replay;playback.spectating=data.live;
    if(data.live){scene.combat.seek(Math.max(0,data.report.duration-2));playback.paused=false;}
    const refresh=async()=>{
      if(generation!==warWatch||scene.combat.replay!==playback||page!=='system')return;
      try{const update=await read();if(scene.combat.replay!==playback)return;playback.record=update.record;playback.duration=update.report.duration;playback.spectating=update.live;playback.deaths=new Map(update.record.events.filter(e=>e.type==='destroy').map(e=>[e.shipId,e.tick]));if(!playback.userPaused)playback.paused=false;if(update.live)setTimeout(refresh,2000);}catch(error){toast(error.message);}
    };
    if(data.live)setTimeout(refresh,2000);
  }
