      html+='<div class="detail-line"><span>结果</span><b>'+(({attacker:'进攻方胜利',defender:'防守方胜利',draw:'战斗结束 · 平局'})[r.winner]||esc(r.winner||'战斗已结束'))+'</b></div><button class="primary" data-replay="'+esc(r.id)+'">观看三维回放 ↗</button>';
      for(const[side,name]of[['attacker','进攻方'],['defender','防守方']])html+='<h3>'+name+'存活</h3>'+tableFleet(r.survivors?.[side])+'<h3>'+name+'损失</h3>'+tableFleet(r.losses?.[side]);
      if(r.loot)html+='<h3>'+(r.defending?'被掠夺资源':'战利品')+'</h3>'+costs(r.loot,false);
